import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  users: defineTable({
    name: v.string(),
  }),
  posts: defineTable({
    title: v.string(),
    content: v.string(),
    author_id: v.id("users"),
  }).index("by_author", ["author_id"]),
  tags: defineTable({
    name: v.string(),
  }),
  post_tags: defineTable({
    post_id: v.id("posts"),
    tag_id: v.id("tags"),
  })
    .index("by_post", ["post_id"])
    .index("by_tag", ["tag_id"])
    .index("by_post_tag", ["post_id", "tag_id"]),
});

import { mutation } from "convex/server";
import { v } from "convex/values";

export const createUser = mutation({
  args: { name: v.string() },
  handler: async (ctx, args) => {
    return ctx.db.insert("users", { name: args.name });
  },
});

export const createPost = mutation({
  args: {
    title: v.string(),
    content: v.string(),
    authorId: v.id("users"),
  },
  handler: async (ctx, args) => {
    return ctx.db.insert("posts", {
      title: args.title,
      content: args.content,
      author_id: args.authorId,
    });
  },
});

export const createTag = mutation({
  args: { name: v.string() },
  handler: async (ctx, args) => {
    return ctx.db.insert("tags", { name: args.name });
  },
});

export const addTagToPost = mutation({
  args: {
    postId: v.id("posts"),
    tagId: v.id("tags"),
  },
  handler: async (ctx, args) => {
    const existing = await ctx.db
      .query("post_tags")
      .withIndex("by_post_tag", (q) =>
        q.eq("post_id", args.postId).eq("tag_id", args.tagId),
      )
      .first();

    if (existing) {
      return existing._id;
    }

    return ctx.db.insert("post_tags", {
      post_id: args.postId,
      tag_id: args.tagId,
    });
  },
});

import { query } from "convex/server";

export const getUsersWithPosts = query({
  args: {},
  handler: async (ctx) => {
    const users = await ctx.db.query("users").collect();

    const usersWithPosts = await Promise.all(
      users.map(async (user) => {
        const posts = await ctx.db
          .query("posts")
          .withIndex("by_author", (q) => q.eq("author_id", user._id))
          .collect();

        return {
          ...user,
          posts,
        };
      }),
    );

    return usersWithPosts;
  },
});

export const getPostsWithTags = query({
  args: {},
  handler: async (ctx) => {
    const posts = await ctx.db.query("posts").collect();

    const postsWithTags = await Promise.all(
      posts.map(async (post) => {
        const author = await ctx.db.get(post.author_id);
        const postTags = await ctx.db
          .query("post_tags")
          .withIndex("by_post", (q) => q.eq("post_id", post._id))
          .collect();
        const tags = await Promise.all(
          postTags.map((postTag) => ctx.db.get(postTag.tag_id)),
        );

        return {
          ...post,
          author,
          tags: tags.filter((tag) => tag !== null),
        };
      }),
    );

    return postsWithTags;
  },
});

